fn dispatch(owner:&OwnerStore,method:&str,args:&Value,authorization:Option<&LibraryAuthorization>,request:&WorkerRequest,broker:&WorkerBroker,workspace:&Path)->Result<Value,LibraryError> {
    match method {
        "snapshot" => {  let result=owner.snapshot()?; produced(workspace,&result) },
        "set_global_setting" => { let name:String=arg(args,"name")?; let value:String=arg(args,"value")?; let result=owner.set_global_setting(&name, &value)?; produced(workspace,&result) },
        "set_game_setting" => { let game_id:String=arg(args,"game_id")?; let name:String=arg(args,"name")?; let value:String=arg(args,"value")?; let result=owner.set_game_setting(&game_id, &name, &value)?; produced(workspace,&result) },
        "get_global_setting" => { let name:String=arg(args,"name")?; let result=owner.get_global_setting(&name)?; produced(workspace,&result) },
        "get_game_setting" => { let game_id:String=arg(args,"game_id")?; let name:String=arg(args,"name")?; let result=owner.get_game_setting(&game_id, &name)?; produced(workspace,&result) },
        "get_settings" => { let request_arg:SettingsGetParams=arg(args,"request")?; let result=owner.get_settings(auth(authorization)?,&request_arg)?; produced(workspace,&result) },
        "update_settings" => { let key:String=arg(args,"key")?; let request_arg:SettingsUpdateParams=arg(args,"request")?; let schema:Option<Value>=arg(args,"schema")?; let result=owner.update_settings(auth(authorization)?,&key,&request_arg,schema.as_ref())?; produced(workspace,&result) },
        "list_games" => { let request_arg:GamesListParams=arg(args,"request")?; let result=owner.list_games(auth(authorization)?, &request_arg)?; produced(workspace,&result) },
        "register_game" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:GameEnrollmentRequest=arg(args,"request")?; let result=owner.register_game(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "registered_installation" => { let installation_id:String=arg(args,"installation_id")?; let result=owner.registered_installation(auth(authorization)?, &installation_id)?; produced(workspace,&result) },
        "list_profiles" => { let request_arg:ProfilesListParams=arg(args,"request")?; let result=owner.list_profiles(auth(authorization)?, &request_arg)?; produced(workspace,&result) },
        "create_profile" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:ProfilesCreateParams=arg(args,"request")?; let result=owner.create_profile(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "update_profile" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:ProfilesUpdateParams=arg(args,"request")?; let result=owner.update_profile(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "activate_profile" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:ProfilesActivateParams=arg(args,"request")?; let result=owner.activate_profile(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "delete_profile_command" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:ProfilesDeleteParams=arg(args,"request")?; let result=owner.delete_profile_command(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "clone_profile" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:ProfilesCloneParams=arg(args,"request")?; let result=owner.clone_profile(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "list_groups" => { let request_arg:GroupsListParams=arg(args,"request")?; let result=owner.list_groups(auth(authorization)?, &request_arg)?; produced(workspace,&result) },
        "create_group" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:GroupsCreateParams=arg(args,"request")?; let result=owner.create_group(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "update_group" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:GroupsUpdateParams=arg(args,"request")?; let result=owner.update_group(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "move_group" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:GroupsMoveParams=arg(args,"request")?; let result=owner.move_group(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "delete_group_command" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:GroupsDeleteParams=arg(args,"request")?; let result=owner.delete_group_command(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "list_mods" => { let request_arg:ModsListParams=arg(args,"request")?; let result=owner.list_mods(auth(authorization)?, &request_arg)?; produced(workspace,&result) },
        "get_mod" => { let request_arg:ModsGetParams=arg(args,"request")?; let result=owner.get_mod(auth(authorization)?, &request_arg)?; produced(workspace,&result) },
        "rename_mod" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:ModsRenameParams=arg(args,"request")?; let result=owner.rename_mod(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "set_mod_enabled" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:ModsSetEnabledParams=arg(args,"request")?; let result=owner.set_mod_enabled(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "set_mods_enabled_batch" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:ModsSetEnabledBatchParams=arg(args,"request")?; let result=owner.set_mods_enabled_batch(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "move_mod" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:ModsMoveParams=arg(args,"request")?; let result=owner.move_mod(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "remove_mod" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:ModsRemoveParams=arg(args,"request")?; let result=owner.remove_mod(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "cleanup_missing_mods" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:ModsCleanupMissingParams=arg(args,"request")?; let result=owner.cleanup_missing_mods(auth(authorization)?, &idempotency_key, &request_arg)?; produced(workspace,&result) },
        "acquire_profile_content_guard" => { let guard_id:String=arg(args,"guard_id")?; let profile_id:String=arg(args,"profile_id")?; let expected_content_revision:u64=arg(args,"expected_content_revision")?; let target_incarnation_id:String=arg(args,"target_incarnation_id")?; let owner_generation:String=arg(args,"owner_generation")?; let result=owner.acquire_profile_content_guard(auth(authorization)?, &guard_id, &profile_id, expected_content_revision, &target_incarnation_id, &owner_generation)?; produced(workspace,&result) },
        "validate_profile_content_guard" => { let guard:ProfileContentGuard=arg(args,"guard")?; let result=owner.validate_profile_content_guard(&guard)?; produced(workspace,&result) },
        "release_profile_content_guard" => { let guard:ProfileContentGuard=arg(args,"guard")?; let result=owner.release_profile_content_guard(&guard)?; produced(workspace,&result) },
        "start_download_operation" => { let request_arg:StartDownloadOperation=arg(args,"request")?; let result=owner.start_download_operation(auth(authorization)?, &request_arg)?; produced(workspace,&result) },
        "download_operation" => { let operation_id:String=arg(args,"operation_id")?; let result=owner.download_operation(auth(authorization)?, &operation_id)?; produced(workspace,&result) },
        "start_version_download" => { let idempotency_key:String=arg(args,"idempotency_key")?; let owner_generation:String=arg(args,"owner_generation")?; let module_lock_digest:String=arg(args,"module_lock_digest")?; let request_arg:ModsSetVersionParams=arg(args,"request")?; let result=owner.start_version_download(auth(authorization)?, &idempotency_key, &owner_generation, &module_lock_digest, &request_arg)?; produced(workspace,&result) },
        "download_execution_plan" => { let operation_id:String=arg(args,"operation_id")?; let result=owner.download_execution_plan(auth(authorization)?, &operation_id)?; produced(workspace,&result) },
        "profile_download_state" => { let profile_id:String=arg(args,"profile_id")?; let result=owner.profile_download_state(auth(authorization)?, &profile_id)?; produced(workspace,&result) },
        "set_profile_mod_enabled" => { let request_arg:SetProfileModEnabled=arg(args,"request")?; let result=owner.set_profile_mod_enabled(auth(authorization)?, &request_arg)?; produced(workspace,&result) },
        "delete_profile_mod" => { let request_arg:DeleteProfileMod=arg(args,"request")?; let result=owner.delete_profile_mod(auth(authorization)?, &request_arg)?; produced(workspace,&result) },
        "mark_download_running" => { let operation_id:String=arg(args,"operation_id")?; let fence_epoch:u64=arg(args,"fence_epoch")?; let owner_generation:String=arg(args,"owner_generation")?; let result=owner.mark_download_running(&operation_id, fence_epoch, &owner_generation)?; produced(workspace,&result) },
        "heartbeat_download_operation" => { let operation_id:String=arg(args,"operation_id")?; let fence_epoch:u64=arg(args,"fence_epoch")?; let owner_generation:String=arg(args,"owner_generation")?; let result=owner.heartbeat_download_operation(&operation_id, fence_epoch, &owner_generation)?; produced(workspace,&result) },
        "record_download_artifact" => { let operation_id:String=arg(args,"operation_id")?; let fence_epoch:u64=arg(args,"fence_epoch")?; let owner_generation:String=arg(args,"owner_generation")?; let item_id:String=arg(args,"item_id")?; let grant_id:String=arg(args,"grant")?; let grant=ArtifactGrant::from_worker_request(request,&grant_id).map_err(|_|LibraryError::ArtifactNotVerified(grant_id))?; let result=owner.record_download_artifact(auth(authorization)?, &operation_id, fence_epoch, &owner_generation, &item_id, &grant)?; produced(workspace,&result) },
        "apply_download_operation" => { let operation_id:String=arg(args,"operation_id")?; let fence_epoch:u64=arg(args,"fence_epoch")?; let owner_generation:String=arg(args,"owner_generation")?; let entries:Vec<Value>=arg(args,"artifacts")?; let grants=entries.iter().map(|a|ArtifactGrant::from_worker_request(request,a["grantId"].as_str().unwrap_or(""))).collect::<Result<Vec<_>,_>>().map_err(|_|LibraryError::ArtifactNotVerified("operation artifact".into()))?; let artifacts=entries.iter().zip(grants.iter()).map(|(entry,grant)|AppliedArtifact {item_id:entry["itemId"].as_str().unwrap_or(""),grant}).collect::<Vec<_>>(); let result=owner.apply_download_operation(auth(authorization)?, &operation_id, fence_epoch, &owner_generation, &artifacts)?; produced(workspace,&result) },
        "fail_download_operation" => { let operation_id:String=arg(args,"operation_id")?; let fence_epoch:u64=arg(args,"fence_epoch")?; let owner_generation:String=arg(args,"owner_generation")?; let error_code:String=arg(args,"error_code")?; let details:Value=arg(args,"details")?; let result=owner.fail_download_operation(auth(authorization)?, &operation_id, fence_epoch, &owner_generation, &error_code, details)?; produced(workspace,&result) },
        "cancel_download_operation" => { let operation_id:String=arg(args,"operation_id")?; let result=owner.cancel_download_operation(auth(authorization)?, &operation_id)?; produced(workspace,&result) },
        "mark_expired_download_leases_suspect" => { let heartbeat_before_ms:i64=arg(args,"heartbeat_before_ms")?; let result=owner.mark_expired_download_leases_suspect(heartbeat_before_ms)?; produced(workspace,&result) },
        "recover_download_operations" => { let current_generation:String=arg(args,"current_generation")?; let result=owner.recover_download_operations(&current_generation)?; produced(workspace,&result) },
        "resume_download_operation" => { let operation_id:String=arg(args,"operation_id")?; let expected_content_revision:u64=arg(args,"expected_content_revision")?; let owner_generation:String=arg(args,"owner_generation")?; let result=owner.resume_download_operation(auth(authorization)?, &operation_id, expected_content_revision, &owner_generation)?; produced(workspace,&result) },
        "retained_artifact_digests" => {  let result=owner.retained_artifact_digests(auth(authorization)?)?; produced(workspace,&result) },
        "profile_content_capability" => { let profile_id:String=arg(args,"profile_id")?; let result=owner.profile_content_capability(auth(authorization)?, &profile_id)?; produced(workspace,&result) },
        "pending_outbox" => { let destination:String=arg(args,"destination")?; let limit:usize=arg(args,"limit")?; let result=owner.pending_outbox(&destination, limit)?; produced(workspace,&result) },
        "mark_outbox_delivered" => { let event_id:String=arg(args,"event_id")?; let delivery_ref:String=arg(args,"delivery_ref")?; let result=owner.mark_outbox_delivered(&event_id, &delivery_ref)?; produced(workspace,&result) },
        "recover_profile_content_guards" => { let generation:String=arg(args,"generation")?; let unresolved_profiles:BTreeSet<String>=arg(args,"unresolved_profiles")?; let result=owner.recover_profile_content_guards(&generation, &unresolved_profiles)?; produced(workspace,&result) },
        "backup_snapshot" => {  let result=owner.backup_snapshot()?; produced(workspace,&result) },
        "ensure_backup_quiescent" => {  let result=owner.ensure_backup_quiescent()?; produced(workspace,&result) },
        "import_empty_snapshot" => { let snapshot:LibrarySnapshot=arg(args,"snapshot")?; let result=owner.import_empty_snapshot(&snapshot)?; produced(workspace,&result) },
        "source_add_target" => { let request_arg:SourceAddRequest=arg(args,"request")?; let result=owner.source_add_target(auth(authorization)?, &request_arg)?; produced(workspace,&result) },
        "source_add_result" => { let key:String=arg(args,"key")?; let request_arg:SourceAddRequest=arg(args,"request")?; let local:bool=arg(args,"local")?; let result=owner.source_add_result(auth(authorization)?, &key, &request_arg, local)?; produced(workspace,&result) },
        "commit_source_add" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:SourceAddRequest=arg(args,"request")?; let target:SourceAddTarget=arg(args,"target")?; let metadata:SourceAddMetadata=arg(args,"metadata")?; if request_arg.reference.source_id=="local" {return Err(LibraryError::PermissionDenied("local addition requires verified grant".into()));} let result=owner.commit_source_add(auth(authorization)?, &idempotency_key, &request_arg, &target, &metadata)?; produced(workspace,&result) },
        "commit_local_source_add" => { let idempotency_key:String=arg(args,"idempotency_key")?; let request_arg:SourceAddRequest=arg(args,"request")?; let target:SourceAddTarget=arg(args,"target")?; let metadata:SourceAddMetadata=arg(args,"metadata")?; let owner_generation:String=arg(args,"owner_generation")?; let id:String=arg(args,"artifact")?; let grant=ArtifactGrant::from_worker_request(request,&id).map_err(|_|LibraryError::ArtifactNotVerified(id))?; let artifact=ArtifactRef {digest:grant.descriptor.digest.clone(),size:grant.descriptor.size,verified:true,media_type:None}; let result=owner.commit_local_source_add(auth(authorization)?, &idempotency_key, &request_arg, &target, &metadata, &artifact, &owner_generation)?; produced(workspace,&result) },
        "import_legacy" => { let id:String=arg(args,"sourceGrant")?; let expected:Option<String>=arg(args,"expectedSourceDigest")?; let grant=ArtifactGrant::from_worker_request(request,&id).map_err(|_|LibraryError::ArtifactNotVerified(id.clone()))?; let vault=ImportVault {broker:broker.clone(),source_grant:id};let source=Path::new(&grant.descriptor.path);let result=match expected {Some(expected)=>owner.import_legacy_checked(source,&expected,&vault)?,None=>owner.import_legacy(source,&vault)?};produced(workspace,&result) },
        _ => Err(LibraryError::NotFound(format!("Library method {method}"))),
    }
}
